css:
/* Benefit grid, four across then three across. The first row is quarters, the rest are thirds,
   centred, so any count wraps the way the reference does. */
[data-bz-node="bs-band"] > .bz-container { max-width: calc(min(90vw, 1440px) + 32px); }
[data-bz-section="benefit-grid-split"] .bz-block { padding-block: 0; }
[data-bz-section="benefit-grid-split"] h2 { margin: 0; text-align: center; font: 700 1.875rem / 1.2 var(--font-heading); color: #000; }
[data-bz-section="benefit-grid-split"] [data-bz-node="bs-row"] { margin-top: 55px; row-gap: 51px; display: flex; flex-wrap: wrap; justify-content: center; }
[data-bz-section="benefit-grid-split"] [data-bz-node="bs-row"] > .bz-col { flex: 0 0 33.3333%; max-width: 33.3333%; grid-column: auto; }
[data-bz-section="benefit-grid-split"] [data-bz-node="bs-row"] > .bz-col:nth-child(-n+4) { flex-basis: 25%; max-width: 25%; }
[data-bz-section="benefit-grid-split"] .bz-figure { margin: 0; display: flex; justify-content: center; align-items: center; height: 56px; }
[data-bz-section="benefit-grid-split"] .bz-figure img { width: auto; max-width: 100%; height: auto; border-radius: 0; }
[data-bz-section="benefit-grid-split"] h3 { margin: 24px 0 0; text-align: center; white-space: pre-line; font: 700 1.5rem / 1.18 var(--font-heading); color: var(--accent); letter-spacing: 0; }
[data-bz-section="benefit-grid-split"] [data-bz-node^="bs-desc"] .bz-text p { margin: 14px auto 0; text-align: center; font: 400 0.95rem / 1.46 var(--font-body); color: #333; max-width: 260px; }
@media (min-width: 1400px) { [data-bz-section="benefit-grid-split"] [data-bz-node^="bs-desc"] .bz-text p { white-space: pre-line; max-width: none; } }
@media (max-width: 1100px) { [data-bz-section="benefit-grid-split"] [data-bz-node="bs-row"] > .bz-col, [data-bz-section="benefit-grid-split"] [data-bz-node="bs-row"] > .bz-col:nth-child(-n+4) { flex-basis: 50%; max-width: 50%; } }
@media (max-width: 640px) { [data-bz-section="benefit-grid-split"] h2 { font-size: 1.5rem; } [data-bz-section="benefit-grid-split"] [data-bz-node="bs-row"] > .bz-col, [data-bz-section="benefit-grid-split"] [data-bz-node="bs-row"] > .bz-col:nth-child(-n+4) { flex-basis: 100%; max-width: 100%; } }
